import {jailCapacity,jailReport} from './jail.js?v=jail-overcrowding-1';
import {civicRoot,civicMembers,civicRoadIds,civicSize,civicCenter} from './civic-footprints.js?v=jail-overcrowding-1';
import {hospitalStaffing,hospitalizationRate} from './hospital.js?v=jail-overcrowding-1';
import {SERVICE_JOBS} from './civic-jobs.js?v=jail-overcrowding-1';
import {RESIDENTIAL_RELIEF} from './residential-cap.js?v=jail-overcrowding-1';
import {SERVICES,DEPARTMENTS,serviceRadius} from './civic.js?v=jail-overcrowding-1';
import {occupancy} from './utilities.js?v=jail-overcrowding-1';
import {educationServiceDemand} from './education.js?v=jail-overcrowding-1';
const CAPACITY_SERVICES=['hospital','school','college','library','museum'];
export function civicFacilityDetails(c,t){
 t=civicRoot(c,t);const definition=SERVICES[t.type];if(!definition)return null;
 const funding=c.civic.funding[definition.department],strike=c.civic.underfunded[definition.department]>=6,reasons=[];
 if(civicMembers(c,t).some(u=>u.fire))reasons.push('Building is on fire');if(civicMembers(c,t).some(u=>u.rubble))reasons.push('Building is destroyed');if(civicMembers(c,t).some(u=>u.radiation))reasons.push('Site is contaminated by radiation');
 if(civicMembers(c,t).some(u=>!u.powered))reasons.push('No electricity');if(!civicRoadIds(c,t).length)reasons.push('No nearby road');if(c.finance.roadCondition<=20)reasons.push('Road network closed by poor condition');if(funding===0)reasons.push('Department funding is zero');if(strike)reasons.push('Department workers are on strike');
 const homes=c.tiles.filter(h=>h.type==='residential'&&h.level&&h.roadIds.some(id=>civicRoadIds(c,t).includes(id))),residents=homes.reduce((sum,h)=>sum+occupancy(h.level)*8,0),profile=educationServiceDemand(c,t.type),weight=1,share=['school','college','library','museum'].includes(t.type)?profile.share:t.type==='hospital'?hospitalizationRate(c):1;
 const demand=residents*share,fundedCapacity=t.type==='hospital'?hospitalStaffing(funding).capacity:t.type==='jail'?jailCapacity(funding).capacity:(definition.capacity||0)*funding/100*weight,capacity=t.serviceActive?fundedCapacity:0;
 const field=t.type==='hospital'?'healthCoverage':profile.field,combinedCoverage=residents?homes.reduce((sum,h)=>sum+(h[field]||0)*occupancy(h.level)*8,0)/residents:0;
 return{definition,funding,strike,reasons,operating:!!t.serviceActive,monthlyCost:definition.upkeep*funding/100,capacityService:CAPACITY_SERVICES.includes(t.type),residents,homes:new Set(homes.map(h=>h.lotRoot??h.y*c.size+h.x)).size,demand,fundedCapacity,capacity,contribution:demand?Math.min(100,capacity/demand*100):0,combinedCoverage,group:t.type==='hospital'?'patients':profile.group,weight};
}
export function civicFacilityReport(c,t){
 t=civicRoot(c,t);const d=civicFacilityDetails(c,t);if(!d)return'';const number=n=>n.toLocaleString(undefined,{maximumFractionDigits:1});
 let body=`<p class="fine">Tile ${t.x+1}, ${t.y+1} · ${civicSize(t)} × ${civicSize(t)} lot</p><p>${d.operating?'Operating.':d.reasons.length?'Not operating: '+d.reasons.join('; ')+'.':'Not operating.'}</p><div class="metric-grid"><div><small>${DEPARTMENTS[d.definition.department]} funding</small><strong>${d.funding}%</strong></div><div><small>Monthly upkeep contribution</small><strong>§${number(d.monthlyCost)}</strong></div></div>`;
 body+=`<p>Civic employment: ${number(t.civicEmployed||0)} / ${d.operating?SERVICE_JOBS[t.type]:0} operating jobs filled. Residents need a working commute to fill these positions.</p>`;
 if(t.type==='hospital'){const staff=hospitalStaffing(d.funding);body+=`<p>Hospital beds: <strong>${staff.beds.toLocaleString()}</strong> · available while operating: ${d.operating?staff.beds.toLocaleString():0}. Funded doctors: <strong>${number(staff.doctors)}</strong>. Patient demand: ${number(hospitalizationRate(c)*100)}% of residents, including pollution effects.</p><p>Funding pays for doctors; it does not add beds. Each doctor can care for 15 patients. Add a connected hospital when beds are full. Staffing capacity is limited by available beds.</p>`;}
 if(d.capacityService)body+=`<h3>Road-connected service area</h3><div class="metric-grid"><div><small>Occupied homes reached</small><strong>${d.homes}</strong></div><div><small>Residents on these road networks</small><strong>${number(d.residents)}</strong></div><div><small>Demand · ${d.group}</small><strong>${number(d.demand)}</strong></div><div><small>Operating capacity contribution</small><strong>${number(d.capacity)}</strong></div><div><small>This facility’s coverage contribution</small><strong>${number(d.contribution)}%</strong></div><div><small>Combined local coverage</small><strong>${number(d.combinedCoverage)}%</strong></div></div><p>${d.residents?'Each residential building is counted once when any of its tiles is reached. Resident demand includes only the connected tiles, matching the service simulation. This facility shares its capacity across these connected homes. Contributions can overlap other facilities; combined coverage is capped at 100% per home.':'No occupied homes share a road network with this facility. Connecting a road only at the building is not enough to reach a disconnected neighborhood.'}</p>${t.type!=='hospital'&&d.group!=='residents'?'<p>Demand uses the city’s age mix: schools serve ages 0–14, colleges ages 15–24, and libraries and museums support retention for ages 25+. School and college places are separate; adding one does not replace the other. Age cutoffs are reconstruction estimates.</p>':''}<p>${!d.operating?'Restore the missing service conditions to use its funded contribution of '+number(d.fundedCapacity)+'.':d.demand>d.capacity&&d.combinedCoverage<99.9?t.type==='hospital'?'This area has unmet demand. Restore staffing if underfunded; add another connected hospital when beds are full.':'This area has unmet demand. Increase department funding or add another connected facility.':d.demand?'Coverage is sufficient or shared with other facilities. Check other neighborhoods before adding capacity here.':d.residents?'No residents in this age group currently need places.':'Zone and develop homes along a connected road network to use this capacity.'}</p>`;
 else if(t.type==='jail')body+=`<p>This jail contributes ${number(d.capacity)} usable cells and ${number(d.operating?jailCapacity(d.funding).maximum:0)} maximum overcrowded places.</p>${jailReport(c)}`;
 else body+=`<p>Base response radius: ${d.definition.radius} tiles. At this funding level, the operating radius is ${number(serviceRadius(c,t))} tiles. ${t.type==='fire'?'Protection is uniform inside this radius. Overlapping stations provide stronger firefighting. Extra funding above 110% adds little range.':'Coverage weakens with distance; inspect the coverage map for gaps.'}${t.type==='police'?' Jail adequacy also affects police effectiveness. Excessive overlapping precincts reduce neighborhood wellbeing; inspect occupied homes to see the police-presence contribution.':''}</p>`;
 if(t.type==='police'&&d.operating){const center=civicCenter(t),radius=serviceRadius(c,t);if(c.tiles.some(h=>h.type==='residential'&&h.level&&h.policePresence>100&&Math.hypot(h.x-center.x,h.y-center.y)<=radius))body+='<p><strong>Excess police presence in this precinct.</strong> Some residents receive overlapping coverage above the wellbeing optimum. Inspect nearby homes before adding another station or increasing funding.</p>';}
 if(RESIDENTIAL_RELIEF[t.type]){const relief=c.stats.residentialCap?.sources.find(s=>s.type===t.type&&s.x===t.x&&s.y===t.y)?.amount||0;body+=`<p>Residential growth capacity: <strong>+${number(relief)} residents</strong> citywide (${number(RESIDENTIAL_RELIEF[t.type])} while operating and undamaged). This supports growth beyond the city’s population cap; it does not move residents in automatically.</p>`;}
 return body+'<p class="fine">Department bills are rounded after adding their building contributions.</p><button id="inspectCivicDepartment">Review department funding and services</button>';
}
